ngs", "intel_equivilant_price" AS "6f1fc28d-3742-4f40-a60e-9f13b33b4f53.intel_equivilant_price", "existing_savings" AS "6f1fc28d-3742-4f40-a60e-9f13b33b4f53.existing_savings"
